#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v, pos;
} Edge;

static int cmp_by_endpoints(const void *pa, const void *pb) {
    const Edge *a = (const Edge *)pa;
    const Edge *b = (const Edge *)pb;
    if (a->u != b->u) return (a->u > b->u) - (a->u < b->u);
    return (a->v > b->v) - (a->v < b->v);
}

static int cmp_by_sum_desc(const void *pa, const void *pb) {
    const Edge *a = (const Edge *)pa;
    const Edge *b = (const Edge *)pb;
    int sa = a->u + a->v;
    int sb = b->u + b->v;
    return (sb > sa) - (sb < sa);
}

static int range_max(const int *tree, int size, int left, int right) {
    int result = 0;
    left += size;
    right += size;
    while (left <= right) {
        if (left & 1) {
            if (tree[left] > result) result = tree[left];
            left++;
        }
        if (!(right & 1)) {
            if (tree[right] > result) result = tree[right];
            right--;
        }
        left >>= 1;
        right >>= 1;
    }
    return result;
}

static void point_update(int *tree, int size, int pos, int value) {
    int i = size + pos;
    tree[i] = value;
    while (i > 1) {
        i >>= 1;
        tree[i] = tree[i << 1] > tree[(i << 1) | 1]
                      ? tree[i << 1]
                      : tree[(i << 1) | 1];
    }
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int edge_count = 2 * m;
    Edge *edges = (Edge *)malloc((size_t)(edge_count ? edge_count : 1) * sizeof(Edge));
    int *degree = (int *)calloc((size_t)n, sizeof(int));

    for (int i = 0; i < m; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        --a;
        --b;
        edges[2 * i] = (Edge){a, b, 0};
        edges[2 * i + 1] = (Edge){b, a, 0};
        degree[a]++;
        degree[b]++;
    }

    int *offset = (int *)malloc((size_t)(n + 1) * sizeof(int));
    offset[0] = 0;
    for (int i = 0; i < n; i++) {
        offset[i + 1] = offset[i] + degree[i];
    }

    qsort(edges, (size_t)edge_count, sizeof(Edge), cmp_by_endpoints);

    int *neighbors = (int *)malloc((size_t)(edge_count ? edge_count : 1) * sizeof(int));
    for (int i = 0; i < edge_count; i++) {
        edges[i].pos = i;
        neighbors[i] = edges[i].v;
    }

    qsort(edges, (size_t)edge_count, sizeof(Edge), cmp_by_sum_desc);

    int size = 1;
    while (size < edge_count) size <<= 1;
    int *tree = (int *)calloc((size_t)(2 * size), sizeof(int));
    int *answer = (int *)calloc((size_t)n, sizeof(int));

    for (int i = 0; i < edge_count; i++) {
        int a = edges[i].u;
        int b = edges[i].v;

        int lo = offset[b];
        int hi = offset[b + 1];
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (neighbors[mid] <= a)
                lo = mid + 1;
            else
                hi = mid;
        }

        int best = 0;
        if (lo < offset[b + 1]) {
            best = range_max(tree, size, lo, offset[b + 1] - 1);
        }

        int length = best ? best + 1 : 2;
        point_update(tree, size, edges[i].pos, length);

        if (length > answer[a]) answer[a] = length;
    }

    for (int i = 0; i < n; i++) {
        if (answer[i] == 0) answer[i] = 1;
        if (i) printf(" ");
        printf("%d", answer[i]);
    }
    printf("\n");

    free(answer);
    free(tree);
    free(neighbors);
    free(offset);
    free(degree);
    free(edges);
    return 0;
}
